/**
 * Armory entry point.
 *
 * Usage:
 *   tsx src/index.ts          — start daemon (requires ARMORY_KEY + mnemonic.enc)
 *   tsx src/index.ts init     — generate ARMORY_KEY + mnemonic.enc, write key to .env, exit
 *   tsx src/index.ts rekey    — rotate ARMORY_KEY without changing the mnemonic
 *
 * Environment:
 *   ARMORY_KEY          — required for daemon; generated by `init`
 *   ARMORY_SOCKET_PATH  — unix socket path (default: /tmp/armory.sock)
 *   ARMORY_LOG_LEVEL    — debug | info | none  (default: info)
 *   ARMORY_MNEMONIC     — import phrase instead of generating (used during init or by tests)
 *   ARMORY_POOL_SIZE    — number of indices to pre-derive (default: 125)
 *   ARMORY_NO_DOTENV    — set to 1 to skip .env loading (used by tests)
 *   ARMORY_KEYS_DIR     — directory for mnemonic.enc (default: .keys/ next to package root)
 *   ARMORY_ENV_PATH     — path to .env file for init/rekey writes (default: .env next to package root)
 */

// Pin process TZ to UTC — pg-node serializes Date params using the host's
// local TZ, which silently shifts `timestamp without time zone` SQL params
// off by the host offset (paperserv/get_kline_minute round-trip bug 2026-05-16).
process.env.TZ = 'UTC'

import dotenv            from 'dotenv'
import crypto            from 'node:crypto'
import fs                from 'node:fs'
import path              from 'node:path'
import { execFileSync }  from 'node:child_process'
import { fileURLToPath } from 'node:url'

// Resolve package root and load .env BEFORE importing any module that reads
// env vars at init time (e.g. logger reads ARMORY_LOG_LEVEL on load).
const __filename = fileURLToPath(import.meta.url)
const __dirname  = path.dirname(__filename)
const PKG_ROOT   = path.resolve(__dirname, '..')
const ENV_PATH   = process.env.ARMORY_ENV_PATH ?? path.join(PKG_ROOT, '.env')

if (!process.env.ARMORY_NO_DOTENV) {
  dotenv.config({ path: ENV_PATH })
}

// Dynamic imports guarantee these modules are evaluated AFTER dotenv runs,
// so ARMORY_LOG_LEVEL and other env vars are already in process.env.
const { logger }                               = await import('./logger.js')
const { loadOrInitMnemonic, FatalMnemonicError, rekeyMnemonic, MNEMONIC_FILE } = await import('./mnemonic.js')
const { startServer }                          = await import('./server.js')
const { parseCommand, ok, err }                = await import('./protocol.js')
const { deriveAddress, buildAddressPool, expandPool, isValidPath, coinType, pathIndex } = await import('./derivation.js')
const { validatePolicy }                       = await import('./policy.js')
const { checkPolicy, isValidHash, signHash }   = await import('./signer.js')
const { getDescriptor }                        = await import('./actions.js')

const SOCKET_PATH = process.env.ARMORY_SOCKET_PATH ?? '/tmp/armory.sock'

// ── CLI: init ─────────────────────────────────────────────────────────────────

async function runInit(): Promise<void> {
  if (fs.existsSync(ENV_PATH)) {
    const contents = fs.readFileSync(ENV_PATH, 'utf8')
    if (/^ARMORY_KEY\s*=/m.test(contents)) {
      console.error('ARMORY_KEY already set in .env — refusing to overwrite')
      process.exit(1)
    }
  }

  if (fs.existsSync(MNEMONIC_FILE)) {
    console.error('mnemonic.enc already exists — refusing to overwrite. Delete .keys/ to start fresh.')
    process.exit(1)
  }

  const key = crypto.randomBytes(32).toString('hex')

  if (fs.existsSync(ENV_PATH)) {
    const existing = fs.readFileSync(ENV_PATH, 'utf8')
    const suffix   = existing.endsWith('\n') ? '' : '\n'
    fs.appendFileSync(ENV_PATH, `${suffix}ARMORY_KEY=${key}\n`)
  } else {
    fs.writeFileSync(ENV_PATH, `ARMORY_KEY=${key}\n`, { mode: 0o600 })
  }

  console.log('ARMORY_KEY generated and written to .env')

  // Generate or import the mnemonic during init — start will be read-only.
  let mnemonic: string
  try {
    mnemonic = await loadOrInitMnemonic(key)
  } catch (e: unknown) {
    console.error(`Failed to create mnemonic: ${e instanceof Error ? e.message : String(e)}`)
    process.exit(1)
  }

  const action = process.env.ARMORY_MNEMONIC ? 'imported' : 'generated'
  console.log(`mnemonic ${action} and stored in .keys/mnemonic.enc`)

  // Derive and print the hotserv pairing key so it can be copied to hotserv/.env
  const { HDNodeWallet } = await import('ethers')
  const pairingWallet    = HDNodeWallet.fromPhrase(mnemonic, '', "m/44'/60'/0'/0/255")
  console.log(`\nHOTSERV_PAIRING_KEY=${pairingWallet.privateKey}`)
  console.log('Add the above line to hotserv/.env')
}

// ── CLI: rekey ────────────────────────────────────────────────────────────────

async function runRekey(): Promise<void> {
  const armoryKey = process.env.ARMORY_KEY
  if (!armoryKey) {
    console.error('ARMORY_KEY not set — cannot rekey')
    process.exit(1)
  }

  if (!fs.existsSync(MNEMONIC_FILE)) {
    console.error('mnemonic.enc not found — cannot rekey')
    process.exit(1)
  }

  const newKey = crypto.randomBytes(32).toString('hex')

  try {
    await rekeyMnemonic(armoryKey, newKey)
  } catch (e: unknown) {
    console.error(`Rekey failed: ${e instanceof Error ? e.message : String(e)}`)
    process.exit(1)
  }

  if (!process.env.ARMORY_NO_DOTENV) {
    // Update ARMORY_KEY in .env for normal (non-test) usage.
    const envContents = fs.existsSync(ENV_PATH) ? fs.readFileSync(ENV_PATH, 'utf8') : ''
    const updated     = envContents.replace(/^ARMORY_KEY=.*/m, `ARMORY_KEY=${newKey}`)
    if (updated !== envContents) {
      fs.writeFileSync(ENV_PATH, updated)
    } else {
      const suffix = envContents.endsWith('\n') ? '' : '\n'
      fs.appendFileSync(ENV_PATH, `${suffix}ARMORY_KEY=${newKey}\n`)
    }
  }

  // Always print new key to stdout — lets tests capture it without .env parsing.
  console.log(newKey)
}

// ── Daemon ────────────────────────────────────────────────────────────────────

const PAIRING_PATH = "m/44'/60'/0'/0/255"

async function main(): Promise<void> {
  const cmd = process.argv[2]

  if (cmd === 'init') {
    await runInit()
    return
  }

  if (cmd === 'rekey') {
    await runRekey()
    return
  }

  // Startup validation — exit immediately if key is absent or empty.
  const armoryKey = process.env.ARMORY_KEY
  if (!armoryKey) {
    console.error("ARMORY_KEY is not set — run 'npm run init' to generate one")
    process.exit(1)
  }

  logger.info('armory starting')

  // Validate policy addresses — fatal if any are malformed.
  try {
    validatePolicy()
  } catch (e: unknown) {
    console.error(`Policy error: ${e instanceof Error ? e.message : String(e)}`)
    process.exit(1)
  }

  // Guard: mnemonic.enc must exist unless ARMORY_MNEMONIC is set (dev/test import path).
  if (!fs.existsSync(MNEMONIC_FILE) && !process.env.ARMORY_MNEMONIC) {
    console.error("mnemonic.enc not found — run 'armory init' to set up the wallet")
    process.exit(1)
  }

  let mnemonic: string | null = null
  let pool:     Awaited<ReturnType<typeof buildAddressPool>> | null = null

  try {
    mnemonic = await loadOrInitMnemonic(armoryKey)
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e)
    if (e instanceof FatalMnemonicError) {
      console.error(`Fatal: ${msg}`)
      process.exit(1)
    }
    // Existing mnemonic.enc unreadable — run in error state; status reports it.
    logger.error(`mnemonic load failed: ${msg}`)
    mnemonic = null
  }

  if (mnemonic) {
    const poolSize = parseInt(process.env.ARMORY_POOL_SIZE ?? '125', 10)
    pool = buildAddressPool(mnemonic, poolSize)
    logger.info(`address pool ready (${pool.evm.length} EVM, ${pool.cosmos.length} Cosmos)`)
  }

  // ── Pairing handshake setup ─────────────────────────────────────────────────
  // Verify that the connecting client holds the same mnemonic by checking they
  // can sign the nonce with the key at the canonical pairing path.
  // If mnemonic failed to load, accept any connection — the armory is in error
  // state and can't sign anything anyway (status returns err).
  let verifyPairing: (nonce: string, sig: string) => boolean

  if (mnemonic) {
    const { recoverAddress } = await import('ethers')
    const pairingAddr = deriveAddress(mnemonic, PAIRING_PATH).toLowerCase()
    verifyPairing = (nonce: string, sig: string): boolean => {
      try {
        return recoverAddress('0x' + nonce, '0x' + sig).toLowerCase() === pairingAddr
      } catch {
        return false
      }
    }
  } else {
    verifyPairing = () => true
  }

  const dispatch = async (raw: string): Promise<string> => {
    const { cmd, args } = parseCommand(raw)
    logger.debug(`command: ${cmd}`)

    if (!mnemonic) {
      return err('mnemonic not loaded')
    }

    switch (cmd) {
      case 'status':
        return ok('ready')

      case 'noop':
        // Liveness primitive. Exercises pairing + framing + dispatch without
        // doing any cryptographic work. Used by tradeserv's
        // /internal/armory/health (via hotserv pass-through) for the
        // webserv readiness probe.
        return ok('alive')

      case 'derive': {
        const [path] = args
        if (!path || !isValidPath(path)) return err('invalid command')
        const coin = coinType(path)
        const idx  = pathIndex(path)
        if (coin === 60) {
          if (idx >= pool!.evm.length) expandPool(pool!, mnemonic, idx + 1)
          return ok(pool!.evm[idx])
        }
        if (coin === 118) {
          if (idx >= pool!.cosmos.length) expandPool(pool!, mnemonic, idx + 1)
          return ok(pool!.cosmos[idx])
        }
        return err('invalid command')
      }

      case 'sign': {
        if (!pool) return err('mnemonic not loaded')

        // Wire form: sign <signingPath> <actionType> <base64url(requestJSON)>
        // requestJSON = { artifact, destination? }. armory recomputes the signing
        // hash from the artifact (never a caller digest) and extracts the true
        // recipient from those same bytes (destination binding).
        const [signingPath, actionType, token] = args
        if (args.length !== 3 || !signingPath || !actionType || !token) return err('invalid command')
        if (!isValidPath(signingPath)) return err('invalid command')

        // Step 1 — decode base64url → JSON. Malformed input → invalid command.
        if (!/^[A-Za-z0-9_-]+$/.test(token)) return err('invalid command')
        let req: {
          artifact?:    { kind?: string; unsignedTx?: unknown; action?: unknown }
          destination?: unknown
        }
        try {
          req = JSON.parse(Buffer.from(token, 'base64url').toString('utf8'))
        } catch {
          return err('invalid command')
        }
        if (!req || typeof req !== 'object' || Array.isArray(req)) return err('invalid command')

        const artifact = req.artifact
        if (!artifact || typeof artifact !== 'object' || Array.isArray(artifact)) return err('invalid command')

        const destHint = req.destination == null ? null : req.destination
        if (destHint !== null && typeof destHint !== 'string') return err('invalid command')

        // Step 2 — resolve the action descriptor. Unknown actionType → denied.
        const descriptor = getDescriptor(actionType)
        if (!descriptor) return err('sign request denied')

        // Artifact kind must match the action's expected kind.
        if (artifact.kind !== descriptor.artifactKind) return err('invalid command')
        if (artifact.kind === 'evm-tx'    && typeof artifact.unsignedTx !== 'string') return err('invalid command')
        if (artifact.kind === 'hl-action' && (typeof artifact.action !== 'object' || artifact.action === null)) return err('invalid command')

        // Step 3 — recompute the signing hash from the artifact (fail closed).
        let hashHex: string
        try {
          hashHex = descriptor.recomputeHash(artifact as Parameters<typeof descriptor.recomputeHash>[0])
        } catch {
          return err('sign request denied')
        }
        if (!isValidHash(hashHex)) return err('sign request denied')

        // Step 4 — extract the true recipient from those same bytes (fail closed).
        let recipient
        try {
          recipient = descriptor.extractRecipient(artifact as Parameters<typeof descriptor.extractRecipient>[0])
        } catch {
          recipient = null
        }
        if (!recipient) return err('sign request denied')

        // Step 5 — enforce policy against the EXTRACTED recipient.
        if (!checkPolicy(signingPath, descriptor.category, recipient, destHint, pool)) {
          return err('sign request denied')
        }

        // Step 6 — sign the recomputed hash; return the derived signer address too.
        let signature: string
        try {
          signature = signHash(mnemonic, signingPath, hashHex)
        } catch {
          return err('sign request denied')
        }
        const address = deriveAddress(mnemonic, signingPath)
        return ok(`${address} ${signature}`)
      }

      default:
        return err('unknown command')
    }
  }

  await startServer(SOCKET_PATH, verifyPairing, dispatch)
  logger.info('armory ready')
  notifySystemdReady()
}

// Inform systemd we're past the listen() barrier so units with
// After=armory.service + Requires=armory.service don't get exec-started
// while the socket is still being bound. No-op when not running under
// a Type=notify systemd unit (NOTIFY_SOCKET unset — e.g. dev `iterm-start.sh`,
// tests, direct `tsx src/index.ts`).
//
// We shell out to `systemd-notify --ready` instead of writing to
// NOTIFY_SOCKET ourselves because node's net module only supports
// SOCK_STREAM unix sockets and systemd's notify socket is SOCK_DGRAM.
// The systemd-notify binary ships with every systemd install.
function notifySystemdReady(): void {
  if (!process.env.NOTIFY_SOCKET) return
  try {
    execFileSync('systemd-notify', ['--ready'], { stdio: 'ignore' })
  } catch (err) {
    // Fail loud per CLAUDE.md but do NOT exit — the daemon is
    // functional, only systemd's view of "started" is degraded.
    // Operator will see dependents waiting TimeoutStartSec.
    logger.error(`systemd-notify --ready failed: ${err instanceof Error ? err.message : String(err)}`)
  }
}

main().catch(e => {
  console.error('Fatal:', e instanceof Error ? e.message : String(e))
  process.exit(1)
})
